"""The ``stockroom`` command."""

import csv
import io
import json
import os
import re
import sys

from .common import ParseError, parse_date
from .orders import (
    order_number_key,
    order_status,
    parse_orders,
    price_lines,
    shipment_note,
    shipped_quantities,
    available_on,
)
from .shelves import (
    Movement,
    buy_quantity,
    counted_order,
    find_negative,
    normal_sku,
    parse_catalog,
    parse_movement_lines,
    stock_levels,
    stock_status,
)

CATALOG = "catalog.txt"
MOVEMENTS = "movements.txt"
ORDERS = "orders.txt"

USAGE = """\
usage: stockroom [--dir DIR] COMMAND [ARGS]

commands:
  stock [--json]                         what is on the shelves
  low [--json]                           what needs buying
  history SKU [--json]                   one product's movements
  receive DATE SKU QUANTITY [NOTE]       record stock coming in
  ship DATE SKU QUANTITY [NOTE]          record stock going out
  quote ORDER [--json]                   price an order
  fulfil ORDER DATE                      ship what the shelves can cover
  invoice ORDER [--json]                 price what has shipped
  report [--format text|csv|json]        one row per order
"""

# name: (fewest positional arguments, most, options accepted or None for
#        "everything is taken as typed", files read)
COMMANDS = {
    "stock": (0, 0, ("--json",), (CATALOG, MOVEMENTS)),
    "low": (0, 0, ("--json",), (CATALOG, MOVEMENTS)),
    "history": (1, 1, ("--json",), (CATALOG, MOVEMENTS)),
    "receive": (3, 4, None, (CATALOG, MOVEMENTS)),
    "ship": (3, 4, None, (CATALOG, MOVEMENTS)),
    "quote": (1, 1, ("--json",), (CATALOG, ORDERS)),
    "fulfil": (2, 2, None, (CATALOG, MOVEMENTS, ORDERS)),
    "invoice": (1, 1, ("--json",), (CATALOG, MOVEMENTS, ORDERS)),
    "report": (0, 0, ("--format",), (CATALOG, MOVEMENTS, ORDERS)),
}

FORMATS = ("text", "csv", "json")

_COUNT_RE = re.compile(r"[0-9]+")


class Failure(Exception):
    """Stop with a message on standard error and an exit status."""

    def __init__(self, status, message):
        super().__init__(message)
        self.status = status
        self.message = message


def usage_error(message):
    return Failure(2, message + "\n" + USAGE.rstrip("\n"))


def refused(message):
    return Failure(1, message)


# --------------------------------------------------------------------------
# The command line


class Request:
    def __init__(self):
        self.directory = "."
        self.command = None
        self.args = []
        self.json = False
        self.format = "text"


def parse_command_line(argv):
    request = Request()
    rest = []
    i = 0
    while i < len(argv):
        arg = argv[i]
        if arg == "--dir":
            if i + 1 >= len(argv):
                raise usage_error("option --dir needs a value")
            request.directory = argv[i + 1]
            i += 2
            continue
        if arg.startswith("--dir="):
            request.directory = arg[len("--dir="):]
            i += 1
            continue
        rest.append(arg)
        i += 1

    def is_option(text):
        return text.startswith("-") and text != "-"

    position = next((k for k, a in enumerate(rest) if not is_option(a)), None)
    if position is None:
        if rest:
            raise usage_error("unknown option %s" % rest[0])
        raise usage_error("no command given")
    command = rest[position]
    if command not in COMMANDS:
        raise usage_error("unknown command %r" % command)
    request.command = command
    least, most, options, _ = COMMANDS[command]

    before = rest[:position]
    after = rest[position + 1:]
    if options is None:
        if before:
            raise usage_error("unknown option %s for %s" % (before[0], command))
        positional = after
    else:
        positional = []
        words = before + after
        k = 0
        while k < len(words):
            word = words[k]
            if not is_option(word):
                positional.append(word)
            elif word == "--json" and "--json" in options:
                request.json = True
            elif word == "--format" and "--format" in options:
                if k + 1 >= len(words):
                    raise usage_error("option --format needs a value")
                request.format = words[k + 1]
                k += 1
            elif word.startswith("--format=") and "--format" in options:
                request.format = word[len("--format="):]
            else:
                raise usage_error("unknown option %s for %s" % (word, command))
            k += 1
        if request.format not in FORMATS:
            raise usage_error(
                "bad value %r for --format (use text, csv or json)" % request.format
            )

    if not least <= len(positional) <= most:
        if least == most:
            wanted = "%d argument%s" % (least, "" if least == 1 else "s")
        else:
            wanted = "%d to %d arguments" % (least, most)
        raise usage_error(
            "%s takes %s, got %d" % (command, wanted, len(positional))
        )
    request.args = positional

    date_position = {"receive": 0, "ship": 0, "fulfil": 1}.get(command)
    if date_position is not None:
        text = positional[date_position]
        if parse_date(text) is None:
            raise usage_error("bad date %r (expected YYYY-MM-DD)" % text)
    return request


# --------------------------------------------------------------------------
# Reading the files


def read_file(directory, name, required):
    """Return ``(text, raw_bytes)``; ``(None, None)`` for a missing optional file."""
    path = os.path.join(directory, name)
    try:
        with open(path, "rb") as handle:
            raw = handle.read()
    except FileNotFoundError:
        if required:
            raise Failure(2, "%s: file not found" % name)
        return None, None
    except OSError as error:
        raise Failure(2, "%s: cannot read: %s" % (name, error.strerror or error))
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError as error:
        line = raw[: error.start].count(b"\n") + 1
        raise Failure(2, "%s: line %d: not valid UTF-8" % (name, line))
    return text, raw


class Data:
    """The parsed files a command needs."""

    def __init__(self, directory, names):
        if not os.path.isdir(directory):
            raise Failure(2, "%s: no such folder" % directory)
        self.directory = directory
        texts = {}
        for name in names:
            texts[name] = read_file(directory, name, name == CATALOG)
        self.movements_raw = texts.get(MOVEMENTS, (None, None))[1]

        self.catalog = self._parse(CATALOG, parse_catalog, texts[CATALOG][0])
        self.movements = []
        self.movement_lines = []
        if MOVEMENTS in texts:
            self.movements, self.movement_lines = self._parse(
                MOVEMENTS,
                lambda t: parse_movement_lines(t, self.catalog),
                texts[MOVEMENTS][0] or "",
            )
        self.orders = []
        if ORDERS in texts:
            self.orders = self._parse(
                ORDERS, lambda t: parse_orders(t, self.catalog), texts[ORDERS][0] or ""
            )

    @staticmethod
    def _parse(name, parser, text):
        try:
            return parser(text)
        except ParseError as error:
            raise Failure(1, "%s: %s" % (name, error))

    def order(self, text):
        wanted = text.upper()
        for order in self.orders:
            if order.id == wanted:
                return order
        raise refused("order %s is not in %s" % (text, ORDERS))

    def product(self, text):
        sku = normal_sku(text)
        if sku is None or sku not in self.catalog:
            raise refused("SKU %s is not in %s" % (text, CATALOG))
        return self.catalog[sku]

    def append_movements(self, new):
        """Add movements to the end of movements.txt; return the lines written."""
        lines = [movement_line(m) for m in new]
        payload = "".join(line + "\n" for line in lines)
        raw = self.movements_raw
        if raw and not raw.endswith(b"\n"):
            payload = "\n" + payload
        path = os.path.join(self.directory, MOVEMENTS)
        try:
            with open(path, "ab") as handle:
                handle.write(payload.encode("utf-8"))
        except OSError as error:
            raise Failure(2, "%s: cannot write: %s" % (MOVEMENTS, error.strerror or error))
        return lines


# --------------------------------------------------------------------------
# Output helpers


def money(amount):
    return format(amount, ".2f")


def signed(quantity):
    return "%+d" % quantity


def movement_line(m):
    parts = [m.date.isoformat(), m.sku, signed(m.quantity)]
    if m.note:
        parts.append(m.note)
    return " ".join(parts)


def as_json(value):
    return json.dumps(value, indent=2, ensure_ascii=False) + "\n"


def lines_out(lines):
    return "".join(line + "\n" for line in lines)


# --------------------------------------------------------------------------
# The shelves


def cmd_stock(request, data):
    levels = stock_levels(data.catalog, data.movements)
    rows = []
    for sku in sorted(data.catalog):
        product = data.catalog[sku]
        onhand = levels[sku]
        rows.append((sku, product.name, onhand, stock_status(onhand, product.reorder)))
    if request.json:
        return as_json(
            [{"sku": s, "name": n, "onhand": o, "status": st} for s, n, o, st in rows]
        )
    return lines_out("%s %d %s %s" % (s, o, st, n) for s, n, o, st in rows)


def cmd_low(request, data):
    levels = stock_levels(data.catalog, data.movements)
    rows = []
    for sku in sorted(data.catalog):
        product = data.catalog[sku]
        onhand = levels[sku]
        if stock_status(onhand, product.reorder) != "ok":
            rows.append((sku, onhand, product.reorder, buy_quantity(onhand, product.reorder)))
    if request.json:
        return as_json(
            [{"sku": s, "onhand": o, "reorder": r, "buy": b} for s, o, r, b in rows]
        )
    return lines_out("%s %d %d %d" % row for row in rows)


def cmd_history(request, data):
    product = data.product(request.args[0])
    balance = 0
    rows = []
    for m in counted_order(m for m in data.movements if m.sku == product.sku):
        balance += m.quantity
        rows.append((m.date.isoformat(), signed(m.quantity), balance, m.note))
    if request.json:
        return as_json(
            [{"date": d, "delta": q, "balance": b, "note": n} for d, q, b, n in rows]
        )
    return lines_out(
        " ".join([d, q, str(b)] + ([n] if n else [])) for d, q, b, n in rows
    )


def _add_movement(request, data, direction):
    date_text, sku_text, quantity_text = request.args[:3]
    note = request.args[3] if len(request.args) > 3 else ""
    product = data.product(sku_text)
    if not _COUNT_RE.fullmatch(quantity_text) or int(quantity_text) < 1:
        raise refused("bad quantity %r (expected a whole number of one or more)" % quantity_text)
    if "\n" in note or "\r" in note:
        raise refused("a note may not contain a line break")
    movement = Movement(
        parse_date(date_text), product.sku, direction * int(quantity_text), note.strip(" \t")
    )
    everything = data.movements + [movement]
    bad = find_negative(everything)
    if bad is not None:
        if bad == len(data.movements):
            raise refused(
                "stock of %s would go below zero on %s" % (product.sku, date_text)
            )
        later = everything[bad]
        raise refused(
            "%s: line %d: stock of %s would go below zero on %s"
            % (MOVEMENTS, data.movement_lines[bad], later.sku, later.date.isoformat())
        )
    return lines_out(data.append_movements([movement]))


def cmd_receive(request, data):
    return _add_movement(request, data, +1)


def cmd_ship(request, data):
    return _add_movement(request, data, -1)


# --------------------------------------------------------------------------
# The orders


def quote_output(request, order, quote, header_prefix=""):
    if request.json:
        return as_json(
            {
                "order": order.id,
                "date": order.date.isoformat(),
                "customer": order.customer,
                "lines": [
                    {
                        "sku": line.sku,
                        "quantity": line.quantity,
                        "unit": money(line.unit),
                        "gross": money(line.gross),
                        "discount": money(line.discount),
                        "net": money(line.net),
                    }
                    for line in quote.lines
                ],
                "subtotal": money(quote.subtotal),
                "order_discount": money(quote.order_discount),
                "tax": money(quote.tax),
                "total": money(quote.total),
            }
        )
    out = ["%s%s %s %s" % (header_prefix, order.id, order.date.isoformat(), order.customer)]
    for line in quote.lines:
        out.append(
            "%s %d %s %s %s %s"
            % (
                line.sku,
                line.quantity,
                money(line.unit),
                money(line.gross),
                money(line.discount),
                money(line.net),
            )
        )
    out.append("subtotal %s" % money(quote.subtotal))
    out.append("order discount %s" % money(quote.order_discount))
    out.append("tax %s" % money(quote.tax))
    out.append("total %s" % money(quote.total))
    return lines_out(out)


def shipped_lines(order, movements):
    shipped = shipped_quantities(order, movements)
    return [(sku, shipped[sku]) for sku, _ in order.lines if shipped[sku] > 0]


def cmd_quote(request, data):
    order = data.order(request.args[0])
    return quote_output(request, order, price_lines(order.lines, data.catalog))


def cmd_invoice(request, data):
    order = data.order(request.args[0])
    lines = shipped_lines(order, data.movements)
    if not lines:
        raise refused("nothing has shipped on order %s yet" % order.id)
    return quote_output(
        request, order, price_lines(lines, data.catalog), header_prefix="invoice "
    )


def cmd_fulfil(request, data):
    order = data.order(request.args[0])
    day = parse_date(request.args[1])
    if day < order.date:
        raise refused(
            "cannot ship order %s on %s, before its date %s"
            % (order.id, day.isoformat(), order.date.isoformat())
        )
    before = shipped_quantities(order, data.movements)
    note = shipment_note(order.id)
    new = []
    out = []
    after = {}
    for sku, quantity in order.lines:
        owed = quantity - before[sku]
        send = min(owed, available_on(data.movements, sku, day))
        if send > 0:
            new.append(Movement(day, sku, -send, note))
        after[sku] = before[sku] + send
        out.append("%s shipped %d backordered %d" % (sku, send, owed - send))
    out.append("status %s" % order_status(order, after))
    if new:
        data.append_movements(new)
    return lines_out(out)


def cmd_report(request, data):
    rows = []
    for order in sorted(data.orders, key=lambda o: (o.date, order_number_key(o.id))):
        shipped = shipped_quantities(order, data.movements)
        quoted = price_lines(order.lines, data.catalog).total
        lines = [(sku, shipped[sku]) for sku, _ in order.lines if shipped[sku] > 0]
        invoiced = price_lines(lines, data.catalog).total if lines else None
        rows.append(
            {
                "order": order.id,
                "date": order.date.isoformat(),
                "customer": order.customer,
                "status": order_status(order, shipped),
                "ordered": sum(q for _, q in order.lines),
                "shipped": sum(shipped.values()),
                "quoted": money(quoted),
                "invoiced": money(invoiced) if invoiced is not None else "0.00",
            }
        )
    if request.format == "json":
        return as_json(rows)
    if request.format == "csv":
        buffer = io.StringIO()
        keys = ["order", "date", "customer", "status", "ordered", "shipped", "quoted", "invoiced"]
        writer = csv.DictWriter(buffer, fieldnames=keys, lineterminator="\n")
        writer.writeheader()
        writer.writerows(rows)
        return buffer.getvalue()
    return lines_out(
        "%s %s %s %s %d/%d %s %s"
        % (
            r["order"],
            r["date"],
            r["customer"],
            r["status"],
            r["shipped"],
            r["ordered"],
            r["quoted"],
            r["invoiced"],
        )
        for r in rows
    )


HANDLERS = {
    "stock": cmd_stock,
    "low": cmd_low,
    "history": cmd_history,
    "receive": cmd_receive,
    "ship": cmd_ship,
    "quote": cmd_quote,
    "fulfil": cmd_fulfil,
    "invoice": cmd_invoice,
    "report": cmd_report,
}


# --------------------------------------------------------------------------
# Entry point


def _stream(name):
    stream = getattr(sys, name)
    return getattr(stream, "buffer", None), stream


def _write(name, text):
    buffer, stream = _stream(name)
    if buffer is not None:
        stream.flush()
        buffer.write(text.encode("utf-8"))
        buffer.flush()
    else:
        stream.write(text)
        stream.flush()


def _silence_stdout():
    """After a broken pipe, point stdout at /dev/null so the interpreter's
    final flush does not complain."""
    try:
        devnull = os.open(os.devnull, os.O_WRONLY)
        os.dup2(devnull, sys.stdout.fileno())
        os.close(devnull)
    except (OSError, ValueError, AttributeError):
        pass


def run(argv):
    """Run the command; return ``(status, stdout_text, stderr_text)``."""
    try:
        request = parse_command_line(argv)
        data = Data(request.directory, COMMANDS[request.command][3])
        output = HANDLERS[request.command](request, data)
    except Failure as failure:
        return failure.status, "", "stockroom: %s\n" % failure.message
    return 0, output, ""


def main(argv=None):
    if argv is None:
        argv = sys.argv[1:]
    status, output, errors = run(list(argv))
    if errors:
        try:
            _write("stderr", errors)
        except (BrokenPipeError, OSError):
            pass
    if output:
        try:
            _write("stdout", output)
        except BrokenPipeError:
            _silence_stdout()
            return 0
    return status


if __name__ == "__main__":
    sys.exit(main())
